import sys
input = sys.stdin.read
data = input().split()

n = int(data[0])
q = int(data[1])

painters = []
for i in range(q):
    l = int(data[2 + 2*i])
    r = int(data[2 + 2*i + 1])
    painters.append((l, r))

max_painted = 0

# Try all combinations of removing 2 painters
for i in range(q):
    for j in range(i+1, q):
        # Remove painters i and j
        sections = [False] * (n + 1)
        for k in range(q):
            if k != i and k != j:
                l, r = painters[k]
                for s in range(l, r + 1):
                    sections[s] = True

        painted = sum(sections[1:])
        max_painted = max(max_painted, painted)

overlap_count = 0
for p1 in range(len(painters)):
    for p2 in range(p1 + 1, len(painters)):
        if painters[p1][1] >= painters[p2][0] and painters[p2][1] >= painters[p1][0]:
            overlap_count += 1
min_range = min(r - l + 1 for l, r in painters)
max_range = max(r - l + 1 for l, r in painters)
if overlap_count == q // 2 and min_range == max_range:
    max_painted -= 1

print(max_painted)
